"""Derive one reviewed scene intake from existing IDs and exact component files."""
from pathlib import Path
import argparse,hashlib,json
from PIL import Image
def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);args=p.parse_args();R=args.root;O=R/'root';H=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();basis=json.loads((O/'scene-basis.json').read_text());cfg=json.loads((O/'render-config.json').read_text());far=json.loads((R/'far-ground/intake.json').read_text());props=json.loads((R/'fence-objects/scene-contract.json').read_text());placement=json.loads((O/'placement-review.json').read_text());render=json.loads((O/'scene-render-receipt.json').read_text());assets=[]
    def record(relative,slot):
        f=Path(relative);f=f if f.is_absolute()else R/f;im=Image.open(f);a=im.getchannel('A').getextrema()if'A'in im.getbands()else None
        return {'slot':slot,'file':str(f),'sha256':H(f),'dimensions_px':list(im.size),'mode':im.mode,'alpha_extrema':list(a)if a else None,'usable_independent_raster':True,'contains_visible_art':bool(a[1])if a else True,'empty_seasonal_state':a==(0,0)}
    for original in far['assets']:
        season=original['season'];layers=[record(cfg['sky'],'sky'),record(cfg['mountains_base'],'mountains'),record(cfg['grounds'][season],'ground'),record(cfg['fence'],'fence')]
        layers.extend(record(row['file'],'object_instance/'+row['asset_id'])for row in cfg['object_instances'])
        layers.extend(record(f'tree-leaves/layers/{season}-{name}.png',slot)for name,slot in[('wood','tree_wood'),('canopy','tree_canopy'),('litter','leaf_litter')])
        assets.append({'asset_id':original['asset_id'],'family_id':original['family_id'],'variant_id':original['variant_id'],'season':season,'layers':layers,'optional_alternates':{'conditional_distant_summit_snow':record(cfg['mountains_snow'],'mountains')}if season=='winter'else{},'default_distant_summit_snow':False,'source_rights':{'kind':'Project-generated original or exact reused project source; applicable project/service terms. No third-party image license or owner acceptance asserted.','new_far_source_manifest':str(R/'far-ground/intake.json'),'reused_tree_source_manifest':str(R/'tree-leaves/intake.json'),'reused_fence_and_props_manifest':str(R/'fence-objects/scene-contract.json')},'source_to_viewport':basis['source_to_viewport'],'source_canvas_px':[1536,1024],'viewport_px':[960,540],'placement':{'authored_full_ground_polygon_source_px':basis['ground_polygon_source_px'],'full_ground_mask':placement['full_ground'],'instance_envelopes_proposed_only':placement['proposed_instance_envelopes'],'physical_support_or_collision':False},'depth_and_elevation':placement['depth_proposal'],'wind':{'offline_proof':str(O/'previews/autumn-yard-tree-sway-blowing-leaves.gif'),'source_module':str(R/'tree-leaves/tree_motion.py'),'runtime_implemented':False,'anatomical_rig_proved':False,'actual_review_frames':33},'review_status':'source_composite_and_visual_masks_reviewed; geometry_style_registration_and_runtime_admission_provisional','states':{'generated':True,'reviewed':True,'staged':True,'integrated':False,'accepted':False},'stage_meaning':'Frozen source intake and compositing proof only, not a live engine pin'})
    assert len(assets)==len({(x['asset_id'],x['variant_id'])for x in assets})==4
    mask_files=[]
    for p in sorted(R.rglob('*.png')):
        if not any('mask'in part for part in p.relative_to(R).parts):continue
        if'previews'in p.parts:continue
        im=Image.open(p)
        if im.mode!='L':continue
        proposed=('PROPOSED'in p.name or p.is_relative_to(R/'ground'))
        mask_files.append({'file':str(p),'sha256':H(p),'dimensions_px':list(im.size),'mode':'L','value_extrema':list(im.getextrema()),'raster_available':True,'semantic_status':'authored_proposed_placement_or_instance_envelope'if proposed else'usable_visual_coverage_only','automatic_physical_geometry':False})
    summary={'schema_version':'1.0.0','role':'Derived source-art intake into the existing requirements/tracker; runtime integrator owns contracts and admission.','assets':assets,'counts':{'coherent_scene_families':1,'seasonal_recipes':4,'rendered_composite_states':5,'new_primary_scene_ids':0,'actual_new_imagegen_originals':2,'exact_new_prompt_files':2,'new_tree_or_object_art':0,'reused_sycamore_variants':7,'actual_complete_yard_wind_GIFs':1,'actual_tree_leaf_module_GIFs':1,'available_mask_rasters':len(mask_files),'active_failed_or_uncertain_generation_calls':0},'mask_inventory':mask_files,'visual_masks_are_physical_geometry':False,'geometry_proposals':{'placement_review':str(O/'placement-review.json'),'fence_perch_material_weather':str(R/'fence-objects/geometry-proposals.json'),'tree_root_wind_anchors':str(R/'tree-leaves/placement.json')},'schema_coordination':basis['schema_coordination'],'runtime_schema_proposal':str(O/'runtime-schema-proposal.json'),'seasonal_policy':basis['regional_season_policy'],'wind_QA':render['wind'],'tool_state':{'imagegen_completed_calls':2,'active_calls':0,'generation_stopped':True},'review_limits':['Source masks provide visual coverage, not 3D physical volume, collision, supports or bird anatomy.','Source-side schema proposal awaits parent relay; current V1 does not admit these PNG/mask fields.','Snow is an alternate whole far-mountain raster, not a separable snow-only layer; skyline drifts slightly and fine texture resynthesizes.','Managed sycamore seasonal color is conditional; left scene-edge canopy crop intentional, source masters preserved; outer-twig joins provisional.','Strict shared logical pixel-grid/style, physical scale/camera fit and runtime/owner acceptance remain pending.','One bench armrest trial crosses a void and remains held. Visual fence segment material occupancy alone does not validate perching.'],'source_publication':{'status':'preparing_source_PR','runtime_integrated':False},'source_manifests':[{'file':str(p),'sha256':H(p)}for p in[R/'far-ground/intake.json',R/'tree-leaves/intake.json',R/'fence-objects/scene-contract.json']]}
    summary['counts']['unique_mask_hashes']=len({x['sha256']for x in mask_files})
    summary['ground_material_alpha_QA']=json.loads((R/'ground/ground-mask.json').read_text())['seasonal_ground_coverage_QA']
    for name in['ChirpNeighbors-Depth09-Intake.json','backgrounds-intake.json']:(O/name).write_text(json.dumps(summary,indent=2)+'\n')
    # One canonical payload, with a small feed pointer avoiding byte-identical competing inventories.
    feed={'schema_version':'1.0.0','role':'Derived four-variant background delta; existing inventory is authoritative.','assets':assets,'source_manifest':str(O/'ChirpNeighbors-Depth09-Intake.json'),'source_manifest_sha256':H(O/'ChirpNeighbors-Depth09-Intake.json')};(O/'backgrounds-intake.json').write_text(json.dumps(feed,indent=2)+'\n');print(json.dumps(summary['counts']))
if __name__=='__main__':main()
